import json
import math
import platform
import time
from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version
from itertools import combinations
from numbers import Integral

import networkx as nx
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def build_hub_connection_graph(coordinates_km, connection_radius_km):
    """Compute every Euclidean distance before applying the connectivity rule."""
    radius = float(connection_radius_km)
    if not math.isfinite(radius) or radius < 0:
        raise ValueError("connection_radius_km must be finite and nonnegative.")

    coordinates = {}
    for hub, coordinate in coordinates_km.items():
        point = np.asarray(coordinate, dtype=float)
        if point.shape != (2,) or not np.all(np.isfinite(point)):
            raise ValueError(f"Invalid two-dimensional coordinate for {hub!r}.")
        coordinates[hub] = point

    graph = nx.Graph()
    graph.add_nodes_from(coordinates)
    distances = []

    for u, v in combinations(coordinates, 2):
        distance = float(np.linalg.norm(coordinates[u] - coordinates[v]))
        connected = distance <= radius
        distances.append(
            {
                "hubs": [u, v],
                "distance_km": distance,
                "connected": connected,
            }
        )
        if connected:
            graph.add_edge(u, v, distance_km=distance)

    return graph, distances


def _parse_reference_partition(partition, vertices):
    """
    Accept two node collections, a zone-to-nodes dictionary, or a
    node-to-zone dictionary. The two zones must cover every vertex exactly once.
    """
    if partition is None:
        return None

    vertex_set = set(vertices)
    if isinstance(partition, Mapping):
        if set(partition) == vertex_set:
            grouped = {}
            for vertex in vertices:
                grouped.setdefault(partition[vertex], []).append(vertex)
            groups = list(grouped.values())
        else:
            groups = list(partition.values())
    else:
        groups = list(partition)

    if len(groups) != 2:
        raise ValueError("known_reference_partition must contain exactly two zones.")

    a, b = map(set, groups)
    if not a or not b or a & b or a | b != vertex_set:
        raise ValueError(
            "Reference zones must be nonempty, disjoint, and cover all vertices."
        )

    mask = sum(1 << i for i, vertex in enumerate(vertices) if vertex in b)
    full_mask = (1 << len(vertices)) - 1
    return full_mask ^ mask if mask & 1 else mask


def _minimization_ratio(value, optimum):
    """Cost/optimum: one is optimal; None denotes no finite ratio."""
    if optimum == 0.0:
        return 1.0 if value == 0.0 else None
    return float(value / optimum)


def _package_versions():
    versions = {"python": platform.python_version()}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx"):
        try:
            versions[package] = version(package)
        except PackageNotFoundError:
            versions[package] = "unknown"
    return versions


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=1,
    lambda_balance=0.8,
    lambda_cut=3.0,
    opt_shots=256,
    final_shots=1024,
    maxiter=40,
    n_repro_runs=3,
    seed=42,
):
    """
    Shot-based QAOA with classical feasible decoding and local refinement.

    Only nonempty zones are hard-constrained. Balance is a soft preference:
        E = lambda_cut * cut
            + lambda_balance * ((|A| - |B|)^2 - (n mod 2)).
    The parity correction is constant and makes the minimum balance penalty zero.
    Since intra-zone edges = total edges - cut, minimizing cut also maximizes
    the number of intra-zone services; connected zones are reported, not imposed.

    Metrics:
      modularity_score: ordinary unweighted Newman-Girvan modularity.
      normalized_cut_score: cut/volume(A) + cut/volume(B), lower is better.
      balance_constraint_score: min(|A|, |B|)/floor(n/2), higher is better.
      approximation_ratio: E_returned / E_exact, lower is better and >= 1.
      runtime: total solver wall-clock seconds, including all repeats and oracle.
      reproducibility: seeds, versions, per-run results, and variability.

    A separate cut_approximation_ratio benchmarks the unpenalized cut.
    Exhaustive enumeration is used ONLY for benchmarking after all QAOA runs.
    The supplied reference, if any, is independently checked against that oracle.
    Exact benchmarking and statevector simulation are limited here to 20 nodes.
    """
    start_time = time.perf_counter()
    vertices = list(graph_vertices)
    n = len(vertices)

    if not 2 <= n <= 20:
        raise ValueError("This exact-benchmarked implementation supports 2–20 nodes.")
    if len(set(vertices)) != n:
        raise ValueError("graph_vertices must not contain duplicates.")

    integer_options = {
        "p_layers": p_layers,
        "opt_shots": opt_shots,
        "final_shots": final_shots,
        "maxiter": maxiter,
        "n_repro_runs": n_repro_runs,
    }
    for name, value in integer_options.items():
        if isinstance(value, bool) or not isinstance(value, Integral) or value < 1:
            raise ValueError(f"{name} must be a positive integer.")
    if (
        isinstance(seed, bool)
        or not isinstance(seed, Integral)
        or not 0 <= seed < 2**32
    ):
        raise ValueError("seed must be an integer in [0, 2**32).")

    p_layers = int(p_layers)
    opt_shots = int(opt_shots)
    final_shots = int(final_shots)
    maxiter = int(maxiter)
    n_repro_runs = int(n_repro_runs)
    seed = int(seed)
    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)

    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")

    indices = {vertex: i for i, vertex in enumerate(vertices)}
    indexed_edge_set = set()
    for edge in graph_edges:
        endpoints = tuple(edge)
        if len(endpoints) != 2:
            raise ValueError("Every graph edge must have exactly two endpoints.")
        u, v = endpoints
        if u not in indices or v not in indices:
            raise ValueError(f"Unknown vertex in edge {endpoints!r}.")
        if u == v:
            raise ValueError("Self-loops are not supported.")
        indexed_edge_set.add(tuple(sorted((indices[u], indices[v]))))

    indexed_edges = sorted(indexed_edge_set)
    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    graph.add_edges_from((vertices[i], vertices[j]) for i, j in indexed_edges)
    m = len(indexed_edges)
    full_mask = (1 << n) - 1
    reference_mask = _parse_reference_partition(known_reference_partition, vertices)

    def canonical(mask):
        # Complementary assignments describe the same partition; fix hub 0 in A.
        return full_mask ^ mask if mask & 1 else mask

    def cut_size(mask):
        return sum(((mask >> i) ^ (mask >> j)) & 1 for i, j in indexed_edges)

    def imbalance(mask):
        return abs(n - 2 * mask.bit_count())

    def energy(mask):
        return float(
            lambda_cut * cut_size(mask)
            + lambda_balance * (imbalance(mask) ** 2 - n % 2)
        )

    def ordering(mask):
        return energy(mask), cut_size(mask), imbalance(mask), canonical(mask)

    def partition(mask):
        return [
            [vertex for i, vertex in enumerate(vertices) if not (mask >> i) & 1],
            [vertex for i, vertex in enumerate(vertices) if (mask >> i) & 1],
        ]

    def metrics(mask):
        a, b = partition(mask)
        crossing = [
            [vertices[i], vertices[j]]
            for i, j in indexed_edges
            if ((mask >> i) ^ (mask >> j)) & 1
        ]
        cut = len(crossing)
        volumes = [sum(graph.degree(vertex) for vertex in zone) for zone in (a, b)]
        # An isolated zero-volume zone contributes zero to normalized cut.
        normalized_cut = sum(cut / volume if volume else 0.0 for volume in volumes)
        modularity = (
            nx.algorithms.community.quality.modularity(
                graph, [set(a), set(b)], weight=None
            )
            if m
            else 0.0
        )
        return {
            "partition": {"zone_A": a, "zone_B": b},
            "zone_sizes": [len(a), len(b)],
            "cut_edges": crossing,
            "cut_size": cut,
            "intra_zone_edges": m - cut,
            "objective_value": energy(mask),
            "modularity_score": float(modularity),
            "normalized_cut_score": float(normalized_cut),
            "balance_constraint_score": float(min(len(a), len(b)) / (n // 2)),
            "zones_connected": [
                bool(nx.is_connected(graph.subgraph(zone))) for zone in (a, b)
            ],
        }

    def refine_locally(initial_mask):
        """Deterministic descent over feasible single moves and pairwise swaps."""
        current = canonical(initial_mask)
        steps = 0
        while True:
            neighbors = {current}
            for i in range(n):
                candidate = current ^ (1 << i)
                if candidate not in (0, full_mask):
                    neighbors.add(canonical(candidate))
            for i, j in combinations(range(n), 2):
                if ((current >> i) ^ (current >> j)) & 1:
                    candidate = current ^ (1 << i) ^ (1 << j)
                    neighbors.add(canonical(candidate))

            candidate = min(neighbors, key=ordering)
            if ordering(candidate) >= ordering(current):
                return current, steps
            current = candidate
            steps += 1

    # z_i = +1/-1 for bit 0/1:
    # cut = sum_edges (1 - Z_i Z_j)/2,
    # (sum_i Z_i)^2 = n I + 2 sum_{i<j} Z_i Z_j.
    # Identity terms do not affect the circuit but remain in evaluated energies.
    coefficients = {
        (i, j): 2.0 * lambda_balance
        - (lambda_cut / 2.0 if (i, j) in indexed_edge_set else 0.0)
        for i, j in combinations(range(n), 2)
    }
    cost_scale = max(1.0, max(abs(value) for value in coefficients.values()))
    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)

    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for (i, j), coefficient in coefficients.items():
            if coefficient != 0:
                # RZZ(theta) = exp(-i theta Z_i Z_j / 2).
                circuit.rzz(
                    2.0 * gammas[layer] * coefficient / cost_scale, i, j
                )
        for i in range(n):
            circuit.rx(2.0 * betas[layer], i)
    circuit.measure(range(n), range(n))

    simulator = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    compiled = transpile(
        circuit,
        simulator,
        optimization_level=1,
        seed_transpiler=seed,
    )
    parameter_order = list(gammas) + list(betas)
    used_parameters = set(compiled.parameters)

    def sample(parameters, shots, simulator_seed):
        bindings = {
            parameter: float(value)
            for parameter, value in zip(parameter_order, parameters)
            if parameter in used_parameters
        }
        bound = compiled.assign_parameters(bindings, inplace=False)
        counts = simulator.run(
            bound,
            shots=shots,
            seed_simulator=simulator_seed,
        ).result().get_counts()
        # Qiskit strings are c[n-1]...c[0]; integer bit i therefore belongs to hub i.
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in counts.items()
        }

    def expected_energy(counts):
        return float(
            sum(energy(mask) * count for mask, count in counts.items())
            / sum(counts.values())
        )

    run_records = []
    run_masks = []
    child_seeds = np.random.SeedSequence(seed).spawn(n_repro_runs)

    for run_index, child in enumerate(child_seeds):
        run_start = time.perf_counter()
        initial_seed, optimization_seed, measurement_seed = map(
            int, child.generate_state(3, dtype=np.uint32)
        )
        rng = np.random.default_rng(initial_seed)
        initial_parameters = np.concatenate(
            [
                rng.uniform(0.0, np.pi, p_layers),
                rng.uniform(0.0, np.pi / 2.0, p_layers),
            ]
        )
        tracker = {
            "energy": float("inf"),
            "parameters": initial_parameters.copy(),
            "evaluations": 0,
        }

        def objective(parameters):
            # Fixed common-random-number seed makes repeated evaluations at the
            # same parameters reproducible while retaining shot-based estimates.
            value = expected_energy(
                sample(parameters, opt_shots, optimization_seed)
            )
            tracker["evaluations"] += 1
            if value < tracker["energy"]:
                tracker["energy"] = value
                tracker["parameters"] = np.asarray(parameters, dtype=float).copy()
            return value

        optimization = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={"maxiter": maxiter, "rhobeg": 0.5, "tol": 1e-3},
        )
        parameters = tracker["parameters"]
        counts = sample(parameters, final_shots, measurement_seed)

        feasible_counts = {}
        for mask, count in counts.items():
            if mask not in (0, full_mask):
                key = canonical(mask)
                feasible_counts[key] = feasible_counts.get(key, 0) + count

        fallback_used = not feasible_counts
        if feasible_counts:
            sampled_mask = min(feasible_counts, key=ordering)
        else:
            # Feasibility fallback does not consult the exact benchmark.
            sampled_mask = canonical((1 << (n // 2)) - 1)

        selected_mask, refinement_steps = refine_locally(sampled_mask)
        run_masks.append(selected_mask)
        run_records.append(
            {
                "run": run_index,
                "initialization_seed": initial_seed,
                "optimization_simulator_seed": optimization_seed,
                "final_simulator_seed": measurement_seed,
                "parameters": {
                    "gamma": parameters[:p_layers].tolist(),
                    "beta": parameters[p_layers:].tolist(),
                },
                "optimizer_success": bool(optimization.success),
                "optimizer_message": str(optimization.message),
                "objective_evaluations": tracker["evaluations"],
                "best_optimization_expected_energy": float(tracker["energy"]),
                "final_expected_energy": expected_energy(counts),
                "feasible_shot_fraction": float(
                    sum(feasible_counts.values()) / final_shots
                ),
                "classical_feasibility_fallback_used": fallback_used,
                "decoded_objective_before_refinement": energy(sampled_mask),
                "local_refinement_steps": refinement_steps,
                "selected_partition_final_shot_fraction": float(
                    feasible_counts.get(selected_mask, 0) / final_shots
                ),
                "metrics": metrics(selected_mask),
                "runtime": float(time.perf_counter() - run_start),
            }
        )

    # Select only among quantum-seeded, classically refined candidates.
    selected_run = min(
        range(n_repro_runs), key=lambda index: ordering(run_masks[index])
    )
    selected_mask = run_masks[selected_run]

    # Independent exact oracle: enumerate all nonempty partitions once modulo
    # complement symmetry. Its solutions are never fed into QAOA or refinement.
    oracle_start = time.perf_counter()
    exact_mask = None
    exact_key = None
    minimum_cut = math.inf
    for candidate in range(2, 1 << n, 2):
        candidate_key = ordering(candidate)
        minimum_cut = min(minimum_cut, candidate_key[1])
        if exact_key is None or candidate_key < exact_key:
            exact_mask = candidate
            exact_key = candidate_key
    oracle_runtime = time.perf_counter() - oracle_start
    exact_objective = energy(exact_mask)

    for record, mask in zip(run_records, run_masks):
        record["metrics"]["approximation_ratio"] = _minimization_ratio(
            energy(mask), exact_objective
        )
        record["metrics"]["cut_approximation_ratio"] = _minimization_ratio(
            cut_size(mask), minimum_cut
        )

    statistics = {}
    for name in (
        "modularity_score",
        "normalized_cut_score",
        "balance_constraint_score",
        "objective_value",
        "cut_size",
        "approximation_ratio",
    ):
        values = [record["metrics"][name] for record in run_records]
        if all(value is not None for value in values):
            statistics[name] = {
                "mean": float(np.mean(values)),
                "std_population": float(np.std(values, ddof=0)),
                "min": float(min(values)),
                "max": float(max(values)),
            }
        else:
            statistics[name] = {"mean": None, "std_population": None}

    benchmark = {
        "method": "exhaustive enumeration of all nonempty bipartitions",
        "partitions_checked": (1 << (n - 1)) - 1,
        "exact_partition": metrics(exact_mask)["partition"],
        "exact_objective": exact_objective,
        "minimum_nonempty_cut": int(minimum_cut),
        "runtime": float(oracle_runtime),
    }
    if reference_mask is not None:
        supplied_objective = energy(reference_mask)
        benchmark["provided_reference"] = {
            "partition": metrics(reference_mask)["partition"],
            "objective_value": supplied_objective,
            "cut_size": cut_size(reference_mask),
            "is_objective_optimal": bool(
                math.isclose(
                    supplied_objective,
                    exact_objective,
                    rel_tol=1e-10,
                    abs_tol=1e-12,
                )
            ),
        }

    result = metrics(selected_mask)
    result.update(
        {
            "approximation_ratio": _minimization_ratio(
                energy(selected_mask), exact_objective
            ),
            "cut_approximation_ratio": _minimization_ratio(
                cut_size(selected_mask), minimum_cut
            ),
            "selected_run": selected_run,
            "benchmark": benchmark,
            "configuration": {
                "p_layers": p_layers,
                "lambda_balance": lambda_balance,
                "lambda_cut": lambda_cut,
                "opt_shots": opt_shots,
                "final_shots": final_shots,
                "maxiter": maxiter,
                "cost_hamiltonian_scale": cost_scale,
            },
            "metric_definitions": {
                "modularity_score": "Unweighted Newman-Girvan modularity; maximize.",
                "normalized_cut_score": (
                    "cut/volume(A) + cut/volume(B); minimize; "
                    "a zero-volume term is defined as zero."
                ),
                "balance_constraint_score": (
                    "min(zone sizes)/floor(number of vertices/2); "
                    "1 means maximally balanced, including a 2/3 split."
                ),
                "approximation_ratio": (
                    "Returned penalized objective / exact minimum penalized "
                    "objective over nonempty partitions; 1 is optimal. "
                    "0/0 is defined as 1; positive/0 is returned as null."
                ),
                "cut_approximation_ratio": (
                    "Returned cut / minimum cut over nonempty partitions, "
                    "without the soft balance preference."
                ),
            },
            "reproducibility": {
                "base_seed": seed,
                "transpiler_seed": seed,
                "n_runs": n_repro_runs,
                "simulator": "qiskit_aer.AerSimulator(method='statevector')",
                "simulator_threads": 1,
                "package_versions": _package_versions(),
                "seed_policy": (
                    "NumPy SeedSequence spawns independent runs; each run has "
                    "separate initialization, optimization, and final-shot seeds."
                ),
                "replay_note": (
                    "The same inputs, seed, and numerical environment reproduce "
                    "the experiment; runtime is not deterministic. Cross-version "
                    "or cross-platform numerical identity is not guaranteed."
                ),
                "partition_agreement_with_selected_run": float(
                    sum(mask == selected_mask for mask in run_masks) / n_repro_runs
                ),
                "exact_objective_optimal_hit_rate": float(
                    sum(
                        math.isclose(
                            energy(mask),
                            exact_objective,
                            rel_tol=1e-10,
                            abs_tol=1e-12,
                        )
                        for mask in run_masks
                    )
                    / n_repro_runs
                ),
                "statistics": statistics,
                "runs": run_records,
            },
            "runtime_scope": (
                "Total solver wall time, including compilation, every QAOA run, "
                "classical refinement, exact benchmarking, and reporting."
            ),
        }
    )
    result["runtime"] = float(time.perf_counter() - start_time)
    return result


def main():
    workflow_start = time.perf_counter()
    coordinates_km = {
        "H0": (0, 0),
        "H1": (0, 3),
        "H2": (2, 5),
        "H3": (4, 3),
        "H4": (4, 0),
    }
    radius_km = 4.2
    supplied_edges = [
        ("H0", "H1"),
        ("H0", "H4"),
        ("H1", "H2"),
        ("H1", "H3"),
        ("H2", "H3"),
        ("H3", "H4"),
    ]

    # Coordinates, rather than the supplied edge list, determine the graph.
    graph, pairwise_distances = build_hub_connection_graph(
        coordinates_km, radius_km
    )
    if {frozenset(edge) for edge in graph.edges()} != {
        frozenset(edge) for edge in supplied_edges
    }:
        raise ValueError("Coordinate-derived connectivity differs from task edges.")

    result = solve_graph_partition_qaoa(
        graph_vertices=list(graph.nodes()),
        graph_edges=list(graph.edges()),
        known_reference_partition=None,
        p_layers=1,
        lambda_balance=0.8,
        lambda_cut=3.0,
        opt_shots=256,
        final_shots=1024,
        maxiter=40,
        n_repro_runs=3,
        seed=42,
    )
    result["graph"] = {
        "vertices": list(graph.nodes()),
        "edges": [list(edge) for edge in graph.edges()],
        "coordinates_km": coordinates_km,
        "connection_radius_km": radius_km,
        "pairwise_distances": pairwise_distances,
        "supplied_edges_verified": True,
    }
    result["runtime"] = float(time.perf_counter() - workflow_start)
    result["runtime_scope"] = (
        "Total workflow wall time: geographic graph construction and verification, "
        "all solver work, exact benchmarking, and report assembly; excludes printing."
    )
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()

